mapper.update:
UPDATE due_diligence
SET dd_firm_status = 'returned',
    dd_firm_return_reason = #{returnReason}
WHERE application_id = #{applicationId} AND is_deleted = 0
  AND dd_firm_status IN ('assigned', 'in_progress')
  AND dd_firm_id = #{firmId}

